<?php
try { $gateways=new \AmAccount\GatewayStore($config,new \AmAccount\Gateways()); $gatewayConnections=$gateways->connections($resellerId); }
catch (Throwable $e) { echo '<p>Gateway settings unavailable. Install the website update and reload.</p>'; return; }
?>
<h2>PayPal, Stripe &amp; Rampex</h2><p>Customers choose from your enabled gateways during renewal. Each merchant connection is scoped to your reseller account. Credentials stay encrypted on the server. Existing orders retain their original connection when you replace or disable it.</p>
<?php foreach (['paypal'=>'PayPal','stripe'=>'Stripe','rampex'=>'Rampex'] as $provider=>$label): ?>
<details class="am-help"><summary>Connect <?= $label ?></summary><form method="post" autocomplete="off"><?= csrf_field() ?><input type="hidden" name="action" value="gateway_connect"><input type="hidden" name="gateway" value="<?= $provider ?>">
<div class="am-grid"><label class="am-field"><span><?= $label ?> environment</span><select name="mode"><?php if ($provider!=='rampex'): ?><option value="sandbox">Sandbox · no real payment or renewal</option><?php endif; ?><option value="live">Live · real payments and renewals</option></select></label><label class="am-field"><span>Price currency</span><select name="currency"><option>CAD</option><option>USD</option></select></label></div>
<?php if ($provider==='paypal'): ?><label class="am-field"><span>PayPal REST app client ID</span><input name="client_id" required autocomplete="off"></label><label class="am-field"><span>PayPal merchant ID</span><input name="merchant_id" required autocomplete="off"></label><p>Use a REST app owned by your business account. Find its client ID and secret under PayPal Developer → Apps &amp; Credentials in the matching environment; find the merchant ID in business account settings. Verification creates an unapproved 1.00 USD order to verify the payee; it does not charge anyone.</p><?php endif; ?>
<label class="am-field"><span><?= $provider==='paypal'?'PayPal client secret':($provider==='stripe'?'Stripe secret API key':'Rampex merchant API key') ?></span><input type="password" name="secret" required autocomplete="new-password"></label>
<?php if ($provider==='stripe'): ?><p>Use the account's full sk_test_ or sk_live_ secret key from Stripe Developers → API keys. Checkout uses one-time card payments.</p><?php elseif ($provider==='rampex'): ?><p>Rampex Dashboard → Settings → API Keys. Configure your payout wallet there first. Rampex has no sandbox: all checkouts are live. Customers supply an email for checkout. Amounts must satisfy the selected Rampex provider's minimum.</p><?php endif; ?>
<button class="btn btn-primary">Verify &amp; save <?= $label ?> connection</button></form></details>
<?php endforeach; ?>
<?php foreach ($gatewayConnections as $connection): $label=ucfirst($connection['gateway']); ?>
<details class="am-package"><summary><?= e($label.' · '.$connection['mode'].' · '.$connection['currency'].' · '.$connection['business_name']) ?> · <?= (int)$connection['enabled']?'Enabled':'Disabled' ?></summary><div class="am-price">
<p>Merchant: <code><?= e($connection['merchant_id']) ?></code></p><p>Webhook URL: <code><?= e($gateways->webhookUrl($connection['id'])) ?></code></p>
<?php if ($connection['gateway']==='paypal'): ?><p>In the same PayPal REST app and environment, add this webhook URL for <code>CHECKOUT.ORDER.APPROVED</code> and <code>PAYMENT.CAPTURE.COMPLETED</code>. Save its webhook ID below. Approval triggers server capture; a browser return never proves payment.</p><?php elseif ($connection['gateway']==='stripe'): ?><p>Stripe Developers → Webhooks: add this URL for <code>checkout.session.completed</code>, <code>checkout.session.async_payment_succeeded</code>, and <code>checkout.session.expired</code> using API version <code>2026-10-28.endive</code>. Save the endpoint's whsec_ signing secret.</p><?php else: ?><p>Rampex Settings → Webhooks: use this URL and the dashboard webhook secret for <code>payment.completed</code>. Amount and completed settlement are independently checked through the merchant API.</p><?php endif; ?>
<form method="post" autocomplete="off"><?= csrf_field() ?><input type="hidden" name="action" value="gateway_configure"><input type="hidden" name="connection" value="<?= e($connection['id']) ?>"><label class="am-field"><span><?= $connection['gateway']==='paypal'?'Webhook ID':'Webhook signing secret' ?><?= $connection['webhook_saved']?' · saved (blank keeps it)':'' ?></span><input type="password" name="webhook_key" autocomplete="new-password"></label><label class="am-switch"><input type="checkbox" name="enabled" value="1"<?= (int)$connection['enabled']?' checked':'' ?>><span>Enable this <?= e($connection['mode']) ?> connection for new <?= e($connection['currency']) ?> checkouts</span></label><p>Enabling replaces the active <?= e($label) ?> connection for this currency. Also select <?= e($label) ?> in App settings and save.</p><button class="btn">Save <?= e($label) ?> checkout settings</button></form>
</div></details><?php endforeach; ?>
<hr style="border:0;border-top:1px solid var(--border);margin:28px 0">
